<?php
namespace App\Http\Controllers;
use App\Models\{Inventory,StockReview};use Illuminate\Http\Request;
class StockReviewController extends Controller{public function store(Request $r){$data=$r->validate(['branch_id'=>'required|exists:branches,id','notes'=>'nullable|string|max:1000']);abort_unless($r->user()->canAccessBranch((int)$data['branch_id']),403);$base=Inventory::where('inventories.branch_id',$data['branch_id'])->join('products','products.id','=','inventories.product_id');$review=StockReview::create(['branch_id'=>$data['branch_id'],'user_id'=>$r->user()->id,'low_stock_count'=>(clone $base)->whereColumn('inventories.quantity','<=','products.minimum_stock')->where('inventories.quantity','>',0)->count(),'empty_stock_count'=>(clone $base)->where('inventories.quantity',0)->count(),'notes'=>$data['notes']??null]);$this->audit('stock.review.completed',$review,null,$review->toArray());return back()->with('success','Revisión registrada. La próxima corresponde en 5 días.');}}
